import java.util.*;

class Solution {
  public int maxSizeSlices(int[] slices) {
    return Math.max(best(slices, 0, slices.length - 2), best(slices, 1, slices.length - 1));
  }

  private int best(int[] slices, int start, int end) {
    int choose = slices.length / 3;
    int[][] dp = new int[end - start + 2][choose + 1];
    for (int i = 1; i <= end - start + 1; i++)
      for (int j = 1; j <= choose; j++)
        dp[i][j] = Math.max(dp[i - 1][j], slices[start + i - 1] + (i >= 2 ? dp[i - 2][j - 1] : 0));
    return dp[end - start + 1][choose];
  }
}
